window.DOSIK=window.DOSIK||{};DOSIK["yc_supervision"]={"1":[{"t":"def","term":"수퍼비전","text":"상담자의 상담수행을 감독 또는 지도하는 활동이다 · 수퍼바이저가 수퍼바이지에게 지혜와 전문성을 전수하는 것이다 · 상담 분야의 선배 또는 보다 전문적인 위치에 있는 사람이 이 분야의 후배 또는 미숙한 구성원 에게 제공하는 개입이다"},{"t":"tree","title":"수퍼비전의 어원","root":"수퍼비전","branches":[["라틴어","라틴어의 super와 videre의 합성어에서 유래되었다"],["영어","Super(위에서)와 Vision(보다)의 조합으로 ‘감독하다’라는 의미를 갖는다"]]},{"t":"table","title":"학자별 정의","head":["학자","정의"],"rows":[["버나드와 굳이어(J. Bernard & R. Goodyear)","상담분야의 선배가 이 분야의 후배나 미숙한 구성원에게 제공하는 일종의 개입이라 했다"],["길버트와 에번스(M. Gilbert & K. Evans)","수퍼바이저가 지혜와 전문성을 전수하여 수련생 의 상담심리치료를 증진시키는 것이라 했다"],["홀로웨이(E. Holloway)","경험 많은 임상가, 감수성이 뛰어난 교사, 뛰어난 전문가의 눈으로 다른 사람의 작업을 감독 및 지도하는 활동이라고 했다"]]},{"t":"tree","title":"수퍼비전의 특징","root":"수퍼비전","branches":[["관계","수퍼비전 관계는 수퍼비전이 진행되면서 변화한다"],["목적","내담자를 보호하는 것은 수퍼비전의 중요한 목적이다"],["역사","프로이트(S. Freud)의 수요모임이 수퍼비전의 시발점이라 할 수 있다"],["목표","수퍼바이저의 이론적 입장이 수퍼비전의 구체적인 목표에 영향을 줄 수 있다"]]}],"2":[{"t":"def","term":"수요모임","text":"프로이트(S. Freud)의 수요모임이 수퍼비전의 시작이라 할 수 있다"},{"t":"tree","title":"수퍼바이저의 역할","root":"수퍼바이저","branches":[["발달수준","수퍼바이저의 역할은 수퍼바이지의 발달수준에 따라 변화한다"],["행정업무","수퍼바이저가 감독할 내용에는 행정적 업무도 포함된다 · 수퍼바이저가 수퍼바이지를 감독하는 내용에는 행정업무도 포함된다"],["교육","수퍼바이지에게 의료보호 체계에서의 주요 윤리적 이슈에 관해서 교육한다"],["자기돌봄","자기돌봄의 중요성을 인식하고 수퍼바이지가 자기돌봄 전략을 개발하도록 돕는다"],["성장","수퍼바이지가 전문가로서 성장할 수 있도록 조력하는 것은 수퍼바이저의 책무이다"]]},{"t":"tree","title":"수퍼바이저의 책임","root":"수퍼바이저","branches":[["관계","수퍼바이저는 수퍼바이지와 전문적 관계 외의 사적인 관계를 맺지 말아야 한다"],["비밀","수퍼비전을 통해 알게 된 내담자의 비밀이나 사생활을 보호해야 한다"],["경계","수퍼바이지와의 관계에서 전문적, 개인적, 사회적 경계를 확실히 한다"],["서면계획서","수퍼바이지와 함께 작성한 서면계획서에 수퍼비전의 범위와 기대에 관한 내용을 포함한다"]]},{"t":"flow","title":"수퍼비전의 시작","steps":["수퍼비전의 목표를 함께 설정한 후","수퍼바이저와 수퍼바이지가 목표를 달성하기 위한 과업에 착수해야 한다"]}],"3":[{"t":"tree","title":"변별모델","root":"버나드의 변별모델","branches":[["역할과 초점","개별 수퍼바이지의 요구에 맞추어 수퍼바이저의 역할과 초점이 결정된다"],["자문가","상담전략과 개입에 대해 브레인스토밍 하도록 격려한다"]]}],"4":[{"t":"tree","title":"체계적 접근모델","root":"홀로웨이의 체계적 접근모델(SAS)","branches":[["기능","수퍼비전의 기능에는 모델링이 포함되어 있다"],["과제","수퍼비전의 과제로는 상담 기술, 사례개념화, 정서적 자각, 자기평가, 지지하기가 있다"],["성숙 단계","수퍼비전 관계에서 개인적 성향이 증가하고 역할 중심의 관계 성향은 감소 한다"],["종결 단계","수퍼비전 관계의 종결 단계에 이르면 힘의 구조가 변화된다"],["발달단계","수퍼바이저는 교육적 개입을 통해 수련생을 지지한다"]]}],"5":[{"t":"tree","title":"통합발달모델","root":"스톨튼버그와 델워스의 통합발달모델(IDM)","branches":[["발달 측면","수퍼바이지의 발달을 동기, 자율성, 자기-타인 인식 측면에서 수준별 특징으로 제시한다"],["동기","수퍼바이지가 임상적 훈련에 쏟는 노력을 의미한다"],["동기와 불안","수퍼비전에 대한 동기와 불안이 높고, 사례의 개념화에 초점을 둔다"],["수준 2","수퍼바이지는 공감능력이 향상되어 자신에서 내담자로 초점을 맞추게 된다"],["수준 3","수퍼바이지는 상담에서 자기(self)를 사용한다"]]}],"6":[{"t":"tree","title":"병행과정","root":"병행과정","branches":[["뿌리","정신역동적 수퍼비전에 그 뿌리를 두고 있다"],["기초","삼자관계는 병행과정의 기초가 된다"],["전이-역전이","병행과정은 전이-역전이와 관련이 있다"],["학습","수퍼바이저가 수퍼바이지에게 반응하는 것을 보고, 수퍼바이지는 내담자에게 어떻게 반응해야 하는지를 배우게 된다"]]},{"t":"table","title":"병행과정의 연구자","head":["학자","주장"],"rows":[["버나드와 굳이어(J. Bernard & R. Goodyear)","동료 수퍼비전 집단이 병렬과정에 대한 상담 자의 인식을 확장시켜 준다고 제시하였다"],["프라울리-오디아와 샤멋(M. Frawley-O'Dea & J. Samat)","전이, 역전이 반응이 수퍼바이저, 수퍼바이지, 내담자에 의해 공동으로 조성된다고 제시하였다"],["신(新) 설리반학파의 심리학자들","수퍼바이지가 내담자의 전이적 대인관계 방식의 전달자 처럼 행동할 수 있다고 주장했다"],["오스틴과 오스틴(J. Austin & J. Austin)","상담과정과 수퍼비전 과정 사이의 유사한 역동성을 설명하며, 두 과정이 어떻게 서로 연관될 수 있는지에 대해 논의하였다"]]},{"t":"table","title":"수퍼비전 모델","head":["모델","내용"],"rows":[["평형과정 모델","수퍼비전에서 일어나는 역동을 상담장면에서 일어나는 역동의 반복으로 보았다"],["작업동맹 모델","정서적 유대, 목표에 대한 합의, 과제에 대한 합의로 설명한다"],["인간중심 모델","수련생의 잠재력에 대한 믿음을 강조한다"],["인지-행동주의 모델","학습이론의 원칙들을 수퍼비전의 전략으로 사용한다"]]}],"8":[{"t":"tree","title":"해결중심 수퍼비전","root":"해결중심 수퍼비전","branches":[["목표","명확하고 측정가능한 목표를 설정한다"],["변화","수퍼바이지가 변화를 지속하도록 격려한다"],["예외질문","문제가 발생하지 않은 상황을 발견하게 한다"],["기적질문","수퍼바이지가 해결된 미래를 상상하게 하여 목표설정에 도움을 준다"]]}],"9":[{"t":"vs","title":"여성주의와 내러티브 수퍼비전","cols":[{"name":"여성주의","items":["권력과 불평등에 대해 분석한다","다양성과 사회적 맥락을 고려한다","여성주의 치료 이론과 관점을 도입한다","수퍼바이저는 협력 관계를 조성한다"]},{"name":"내러티브","items":["경험에 의미를 부여하는 해석과정 자체에 초점을 둔다","수퍼바이저는 자문가 역할과 언어 사용에 많은 관심을 기울인다","수퍼바이저는 수퍼바이지와 내담자의 이야기를 편집하도록 돕는다","수퍼바이지는 내담자들의 긍정적 변화를 위한 효과적인 방법을 찾도록 돕는다"]}]}],"10":[{"t":"tree","title":"진로상담 수퍼비전","root":"진로상담 수퍼비전","branches":[["과업","수퍼비전 목표와 연결되어야 한다"],["사례개념화","수퍼바이지의 사례개념화 기술을 자연스럽게 촉진시키는 방법이기도 하다"],["목표","목표는 다양하며 사례별로 수퍼비전 방식의 차이가 있다"]]},{"t":"tree","title":"진로상담 수퍼비전의 활동","root":"수퍼비전 활동","branches":[["이론 적용","내담자의 개별적 특성에 맞는 이론을 적용한다"],["녹음","상담회기에 관한 녹음을 재검토한다"],["발달 이론","진로에 대한 발달 이론을 토론한다"],["행동 이론","내담자가 보인 행동에 맞는 이론을 토론한다"],["사례 개념화","사례 개념화를 위해 진로상담 이론을 활용하도록 지도한다"]]}],"11":[{"t":"tree","title":"수퍼비전 관계와 작업동맹","root":"수퍼바이저와 수퍼바이지","branches":[["과정","수퍼비전 과정에 대해 명료화한다"],["불안","수퍼바이저는 수퍼바이지의 불안에 민감해야 한다"],["접근","개인 또는 집단 수퍼비전 접근의 차이점을 의논하고 결정한다"],["기대","수퍼바이저와 수퍼바이지는 수퍼비전에서 기대하는 바를 분명히 논의한다"]]}],"12":[{"t":"vs","title":"집단수퍼비전의 단점과 장점","cols":[{"name":"단점","items":["개인수퍼비전에 비해 비밀이 노출될 개연성이 높으므로 비밀유지에 대해 거듭 강조한다","집단구성원들의 기술 수준이 상이한 집단에서 좀 더 숙련된 구성원들은 필요한 것을 얻지 못 하고 끝나기도 한다","심각한 문제를 안고 있는 수퍼바이지에게 충분한 시간이 주어지지 못한다","수퍼바이지 개인에게 요구되는 충분한 학습제공이 어렵다"]},{"name":"장점","items":["다른 상담양식을 이해하고 수용할 수 있는 또 다른 방법을 볼 수 있게 해준다","수퍼바이지의 자기인식을 현실검증할 수 있게 해준다","수퍼바이지들이 안전한 환경에서 새로운 행동을 시도할 수 있는 기회를 갖게 한다","다른 수퍼바이지의 사례를 통해 다양한 상담개입방법에 대한 이해를 돕는다"]}]},{"t":"flow","title":"집단수퍼비전의 단계","steps":["형성단계 - 수련생들이 누구인지, 서로 어떻게 관계를 이룰지 탐색하는 단계이다","규범단계 - 집단 운영을 위한 규칙 설정이 중요한 단계이다","수행단계 - 집단응집력이 증가되어 이전 단계보다 더 많은 피드백이 일어나는 반면 수퍼바이 저 반응은 감소할 수 있다","종결단계 - 집단경험을 정리하고, 집단에 대한 평가와 함께 개인적 유익이 통합되는 단계이다"]}],"13":[{"t":"def","term":"모델링","text":"수퍼바이저가 수퍼바이지에게 다양한 전문적인 업무를 수행하는 방법을 관찰하도록 가르치는 것이다"},{"t":"tree","title":"모델링 형태의 교육","root":"모델링","branches":[["시기","모델링 형태의 교육은 수퍼비전 과정 전반에 걸쳐 이루어진다"],["태도","수퍼바이저가 수퍼바이지에게 자기수퍼비전 능력을 가질 수 있는 태도를 보여주는 것이 중요 하다"],["시연","수퍼바이지들이 자신의 배운 점을 시연할 기회를 제공하고, 독창적인 스타일을 이 작업에 적 용하도록 격려한다"]]},{"t":"flow","title":"개입의 순서","steps":["상담자의 장점과 긍정적 행동을 먼저 강조한다","처방적 개입과 개념적 개입"]}],"15":[{"t":"tree","title":"평가 계획","root":"평가과정","branches":[["시점","평가과정은 수퍼비전 관계가 시작되는 시점부터 미리 계획되는 것이 좋다"],["계약","수퍼비전 계약을 할 때 평가과정, 방법, 시점 등을 명시적으로 기술할 필요가 있다"],["오리엔테이션","오리엔테이션 시 평가에 대한 준거와 과정을 분명히 하는 것이 좋다"]]},{"t":"tree","title":"피드백","root":"피드백","branches":[["과정과 절차","수퍼바이저와 수퍼바이지가 서로에게 피드백을 주고받는 과정과 절차를 계획하는 것이 중요 하다"],["기관","기관에서의 수퍼바이저 평가나 피드백은 수퍼비전을 마쳤을 때 만족도 평가 등으로 이루어질 수 있다"],["평가를 위한 피드백","평가를 위한 피드백은 상호적이며 지속적이어야 한다"]]},{"t":"tree","title":"종합평가와 개선","root":"평가","branches":[["종합평가","종합평가는 수퍼바이저와 수련생 간 갈등을 일으키기도 한다"],["직면적 개입","개선되어야 할 부분에서 직면적 개입을 활용할 수 있다"]]}],"17":[{"t":"table","title":"수퍼바이저의 발달 단계","head":["단계","특징"],"rows":[["탐색단계","수퍼비전을 전문적 활동으로 보게 된다 · 수퍼바이지에게 미치는 자신의 영향력을 인식하게 된다"],["초기단계","수퍼바이지와 더 동일시하는 경향이 있다"],["확립단계","수퍼바이지와의 신뢰 수준을 촉진시키면서 수퍼바이저로서의 정체성을 확립 하게 된다"],["역할숙련 단계","수퍼비전 문제를 효과적이면서 적절하게 다룰 수 있다"],["정체성 확립단계","수퍼바이저는 수련생과 인지적 수준의 관계에서 벗어나 전인적 수준의 관계로 발전할 수 있다"]]}],"18":[{"t":"def","term":"헤어(R. Hare)","text":"윤리적 의사결정을 이끄는 도덕적 사고를 직관적 차원과 비판적 차원으로 구분하였다"},{"t":"tree","title":"윤리적 의사결정","root":"윤리적 의사결정","branches":[["정보 수집","상황을 설명해 줄 수 있는 정보를 가능한 많이 수집한다"],["윤리지침 검토","자신이 속한 전문가 단체의 규율 또는 원칙이 해당 문제에 적절한 해결 책을 줄 수 있는지 알아본다"],["행동적 조치","가능한 행동적 조치 과정을 고려하기: 브레인스토밍이 유용하다"],["최선의 조치","여러 자원으로부터 모은 정보를 숙고한다"],["다양한 결정","내담자와 결과를 상의하는 것이 중요하다고 본다"]]},{"t":"table","title":"윤리 원칙","head":["원칙","내용"],"rows":[["자율성 존중(respect for autonomy)","개인의 자유와 존엄성에 대한 존중을 의미한다"],["무해성(nonmaleficence)","내담자에게 해를 입힐 수 있는 행동은 피해야 한다"],["선의(beneficence)","내담자에게 진정한 도움이 되도록 할 의무가 있다"],["공정성(justice)","상담서비스를 다양한 배경의 사람들에게 차별 없이 제공해야 한다"]]}],"19":[{"t":"tree","title":"위기 후 대응","root":"위기 사례지도","branches":[["개인상담","회복이 더디고 충격을 많이 받은 상태라면 개인상담으로 의뢰한다"],["상담 재개","상담을 다시 시작할 수 있는지 사정한다"],["영향 점검","위기의 영향을 점검하고 다른 수퍼바이지나 내담자에게 미칠 수 있는 영향을 고려한다"],["경험 처리","위기 상황에 대한 경험을 처리하는데 시간을 충분히 갖도록 격려한다"]]},{"t":"tree","title":"가출 사례 탐색","root":"내담자 탐색","branches":[["가출 경험","내담자의 이전 가출 경험에 대해 살펴보게 한다"],["의사소통","부모님과 내담자 간의 의사소통 방식을 확인하게 한다"],["학교생활","내담자의 학교생활에 대해 탐색하게 한다"],["가출 후 계획","가출 후 계획에 대해 탐색하게 한다"]]}]};
